"use strict";
import { useAccount } from "hooks/useAccount";
import { useVeABXUserLocks } from "hooks/useVeABXLocks";
import { useEffect, useRef, useState } from "react";
import { ChevronLeft, ChevronRight } from "react-feather";
import { useAppDispatch, useAppSelector } from "state/hooks";
import { selectPendingVotes, selectSelectedLock, setSelectedLock } from "state/voting/slice";
import { Flex, Text, styled as UiStyled, useMedia, useSporeColors } from "ui/src";
import { calculateTimeUntilUnlock } from "utils/lockCalculations";
import SingleSlide from "./SingleSlide";
import VoteBottomSliderLoader from "./VoteBottomSliderLoader";
const SliderContainer = UiStyled(Flex, {
  overflow: "hidden",
  margin: "0 auto"
});
const NavButton = UiStyled(Flex, {
  row: true,
  alignItems: "center",
  justifyContent: "center",
  width: 35,
  height: "100%",
  borderRadius: "$rounded8",
  backgroundColor: "$surface1",
  borderWidth: 1,
  borderColor: "$surface3Hovered",
  cursor: "pointer",
  position: "relative",
  hoverStyle: {
    backgroundColor: "$surface1Hovered"
  },
  $lg: {
    position: "absolute",
    borderColor: "$surface3Hovered",
    backgroundColor: "$surface2",
    borderRadius: "$roundedFull",
    height: 26,
    width: 26
  }
});
const Slider = ({ lockStatuses, votingStatusSummary }) => {
  const media = useMedia();
  const account = useAccount();
  const dispatch = useAppDispatch();
  const selectedLock = useAppSelector(selectSelectedLock);
  const pendingVotes = useAppSelector(selectPendingVotes);
  const colors = useSporeColors();
  const { data: userLocks, isLoading } = useVeABXUserLocks(account.address);
  const locksCards = userLocks?.filter((lock) => {
    const isOwner = lock.owner.toLowerCase() === account.address?.toLowerCase();
    const isNotExpired = lock.permanent || !calculateTimeUntilUnlock(lock.lockEnd).expired;
    return isOwner && isNotExpired;
  }) || [];
  const [currentIndex, setCurrentIndex] = useState(0);
  const spaceBetween = media.md ? 0 : 10;
  const [cardWidth, setCardWidth] = useState(200);
  const cardsPerView = media.md ? 1 : 2;
  const maxIndex = Math.max(0, locksCards.length - cardsPerView);
  const sliderContainerRef = useRef(null);
  useEffect(() => {
    if (sliderContainerRef.current) {
      const newCardWidth = sliderContainerRef.current.offsetWidth / cardsPerView - spaceBetween / cardsPerView;
      setCardWidth(newCardWidth);
    }
  }, [sliderContainerRef.current, isLoading]);
  useEffect(() => {
    if (selectedLock && locksCards.length > 0 && cardWidth > 0) {
      const timeoutId = setTimeout(() => {
        const selectedIndex = locksCards.findIndex((lock) => lock.id === selectedLock.id);
        if (selectedIndex !== -1) {
          let targetIndex = selectedIndex;
          if (cardsPerView > 1) {
            const isFullyVisible = selectedIndex >= currentIndex && selectedIndex < currentIndex + cardsPerView;
            if (!isFullyVisible) {
              if (selectedIndex < currentIndex) {
                targetIndex = selectedIndex;
              } else {
                targetIndex = Math.max(0, selectedIndex - cardsPerView + 1);
              }
              setCurrentIndex(Math.min(targetIndex, maxIndex));
            }
          } else {
            setCurrentIndex(Math.min(selectedIndex, maxIndex));
          }
        }
      }, 50);
      return () => clearTimeout(timeoutId);
    }
  }, [selectedLock?.id, locksCards.length, cardWidth]);
  const handlePrev = () => {
    setCurrentIndex((prev) => Math.max(prev - 1, 0));
  };
  const handleNext = () => {
    setCurrentIndex((prev) => {
      let index = prev + 1;
      if (index > maxIndex) {
        index = 0;
      }
      return index;
    });
  };
  if (isLoading) {
    return <VoteBottomSliderLoader />;
  }
  if (locksCards.length === 0) {
    return <Flex row gap={"$spacing16"} flex={1} justifyContent="center" alignItems="center">
        <Text variant="body3" color="$neutral2">
          No locks available. Create a lock to start voting.
        </Text>
      </Flex>;
  }
  const allLocksVoted = votingStatusSummary.unvoted === 0 && votingStatusSummary.total > 0;
  if (allLocksVoted) {
    return <Flex row gap={"$spacing16"} flex={1} justifyContent="center" alignItems="center">
        <Text variant="body4" color="$neutral2">
          All {votingStatusSummary.total} lock{votingStatusSummary.total !== 1 ? "s have" : " has"} already voted this
          epoch. Voting resets every Thursday.
        </Text>
      </Flex>;
  }
  return <Flex
    row
    gap={"$spacing12"}
    flex={1}
    justifyContent="flex-start"
    position="relative"
    $md={{ px: "$spacing8" }}
  >
      <NavButton
    onPress={handlePrev}
    disabled={currentIndex === 0 || locksCards.length <= cardsPerView}
    $md={{ display: "none" }}
  >
        <Text>←</Text>
      </NavButton>

      <Flex
    maxWidth={850}
    width={"100%"}
    backgroundColor={"$surface2Hovered"}
    borderWidth={1}
    borderColor={"$surface3"}
    padding={"$spacing8"}
    borderRadius={"$rounded16"}
    boxShadow={"$md"}
    $md={{ padding: "$none", backgroundColor: "$none", borderWidth: "$none" }}
  >
        <SliderContainer ref={sliderContainerRef}>
          <Flex
    row
    transition="transform 0.5s ease-in-out"
    transform={`translateX(-${currentIndex * cardWidth + spaceBetween * currentIndex}px)`}
  >
            {locksCards.map((lock) => {
    const lockStatus = lockStatuses.find((status) => status.tokenId === lock.id);
    const hasVoted = lockStatus?.hasVoted || false;
    const isSelected = selectedLock?.id === lock.id;
    console.log(`[Slider] Lock #${lock.id}:`, {
      lockStatus: !!lockStatus,
      hasVoted,
      isSelected
    });
    return <SingleSlide
      key={lock.id}
      lock={lock}
      width={cardWidth}
      spaceBetween={spaceBetween}
      isSelected={isSelected}
      selectedPools={isSelected ? pendingVotes.length : 0}
      hasVoted={hasVoted}
      onSelect={() => {
        dispatch(setSelectedLock(lock));
      }}
    />;
  })}
          </Flex>
        </SliderContainer>
      </Flex>

      <NavButton
    onPress={handleNext}
    disabled={currentIndex >= maxIndex || locksCards.length <= cardsPerView}
    $md={{ display: "none" }}
  >
        <Text>→</Text>
      </NavButton>

      <NavButton
    onPress={handlePrev}
    disabled={currentIndex === 0 || locksCards.length <= cardsPerView}
    left={media.md ? -11 : -4}
    top={"50%"}
    transform={"translateY(-50%)"}
    row
    display="none"
    $md={{ display: "flex" }}
  >
        <ChevronLeft size={media.md ? 20 : 24} color={colors.neutral2.val} />
      </NavButton>
      <NavButton
    onPress={handleNext}
    disabled={currentIndex >= maxIndex || locksCards.length <= cardsPerView}
    right={media.md ? -11 : -4}
    top={"50%"}
    transform={"translateY(-50%)"}
    display="none"
    $md={{ display: "flex" }}
  >
        <ChevronRight size={media.md ? 20 : 24} color={colors.neutral2.val} />
      </NavButton>
    </Flex>;
};
export default Slider;
